import logo from './logo.jpg';
import { FaSearch, FaShoppingCart } from 'react-icons/fa';
import { useNavigate } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min';
import { useState } from 'react';

const Menu = () => {
    const navigate = useNavigate();
    const [search, setSearch] = useState("");

    return (
        <nav className="navbar navbar-expand-lg navbar-light bg-white shadow-sm py-2 fixed-top">
            <div className="container">
                {/* Logo */}
                <a className="navbar-brand d-flex align-items-center" href="/home">
                    <img src={logo} alt="Logo" height="40" className="me-2" />
                    <span className="fw-bold fs-5">ABC Shop</span>
                </a>

                {/* Toggler cho mobile */}
                <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#mainNavbar">
                    <span className="navbar-toggler-icon"></span>
                </button>

                {/* Menu nội dung */}
                <div className="collapse navbar-collapse" id="mainNavbar">
                    <ul className="navbar-nav mx-auto mb-2 mb-lg-0">
                        <li className="nav-item">
                            <a className="nav-link" href="/about-us">Về chúng tôi</a>
                        </li>
                        <li className="nav-item">
                            <a className="nav-link" href="/blog">Blog</a>
                        </li>
                        <li className="nav-item dropdown">
                            <a className="nav-link dropdown-toggle" href="#" id="productsDropdown" role="button" data-bs-toggle="dropdown">
                                Sản phẩm
                            </a>
                            <ul className="dropdown-menu">
                                <li><a className="dropdown-item" href="/men">Đồ Nam</a></li>
                                <li><a className="dropdown-item" href="/women">Đồ Nữ</a></li>
                                <li><a className="dropdown-item" href="/kids">Trẻ Em</a></li>
                            </ul>
                        </li>
                        <li className="nav-item">
                            <a className="nav-link" href="/new-arrivals">Hàng mới về</a>
                        </li>
                    </ul>

                    {/* Thanh tìm kiếm + hành động */}
                    <form className="d-flex align-items-center me-3" onSubmit={(e) => e.preventDefault()}>
                        <input
                            className="form-control form-control-sm me-2"
                            type="search"
                            placeholder="Tìm kiếm..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            style={{ width: "140px" }}
                        />
                        <button className="btn btn-outline-secondary btn-sm" type="submit">
                            <FaSearch />
                        </button>
                    </form>

                    <div className="d-flex align-items-center gap-2">
                        <button className="btn btn-outline-primary btn-sm" onClick={() => navigate("/login")}>Đăng nhập</button>
                        <button className="btn btn-primary btn-sm" onClick={() => navigate("/register")}>Đăng ký</button>
                        <button className="btn btn-outline-dark btn-sm" onClick={() => navigate("/giohang")}>
                            <FaShoppingCart />
                        </button>
                    </div>
                </div>
            </div>
        </nav>
    );
};

export default Menu;
